        self = .rgb(red: red, green: green, blue: blue)
    }

    var rawValue: String {
        switch self {
        case .accent:
            "accent"
        case let .rgb(red, green, blue):
            String(format: "#%02X%02X%02X", red, green, blue)
        }
    }
